(7512761, 1199616, 114285, '<td valign="top">Pretty sure this is Melethia, a lovely everyday evening image.<br/> <br/>Edited to add my 2nd guess is actually Johanna...but then again I think that could be my first guess really :)</td>', 'Pretty sure this is Melethia, a lovely everyday evening image. Edited to add my 2nd guess is actually Johanna...but then again I think that could be my first guess really :)', '2017-05-09 00:51:29.000000', NULL, 1),
(7512763, 1199447, 30982, '<td valign="top">A much nicer composition, and gentler handling of the processing than my version.  I like the balance with the clouds and the rocks - they echo each other nicely!</td>', 'A much nicer composition, and gentler handling of the processing than my version.  I like the balance with the clouds and the rocks - they echo each other nicely!', '2017-05-09 01:05:23.000000', NULL, 1),
(7512764, 1199698, 30982, '<td valign="top">Very much my kinda thing - I enjoy finding textures like this, and I enjoy the toned monochrome you chose, too.  Well seen!</td>', 'Very much my kinda thing - I enjoy finding textures like this, and I enjoy the toned monochrome you chose, too.  Well seen!', '2017-05-09 01:06:01.000000', NULL, 1),
(7512765, 1199618, 96751, '<td valign="top">Not her normal subject but sure has her sensitivity to detail.</td>', 'Not her normal subject but sure has her sensitivity to detail.', '2017-05-09 01:07:43.000000', NULL, 1),
(7512767, 1199089, 96751, '<td valign="top">Ha! That is an amazing portrait. And absolutely adorable. I feel like the whites could be a little brighter.</td>', 'Ha! That is an amazing portrait. And absolutely adorable. I feel like the whites could be a little brighter.', '2017-05-09 01:09:14.000000', NULL, 1),
