(7512769, 1199578, 30982, '<td valign="top">I remember shooting from the floor of the church, possibly with Sara, in either York or Rome.  Main reason I shot from the floor was to accommodate for the slow shutter speed!  (Most churches frown on tripods.)  This is quite lovely.  Very peaceful.</td>', 'I remember shooting from the floor of the church, possibly with Sara, in either York or Rome.  Main reason I shot from the floor was to accommodate for the slow shutter speed!  (Most churches frown on tripods.)  This is quite lovely.  Very peaceful.', '2017-05-09 01:10:01.000000', NULL, 1),
(7512770, 1199089, 30982, '<td valign="top">What GREAT eyes!!  I took a shot very similar to this of a cat I was babysitting for a friend who was deployed at the time.  This is better!</td>', 'What GREAT eyes!!  I took a shot very similar to this of a cat I was babysitting for a friend who was deployed at the time.  This is better!', '2017-05-09 01:10:38.000000', NULL, 1),
