(7513381, 1199612, 100831, '<td valign="top">Beautiful... love the angle, the reflection and the message... to say nothing of the amazing contrast.  I KNOW Deb will love this. Great job.</td>', 'Beautiful... love the angle, the reflection and the message... to say nothing of the amazing contrast.  I KNOW Deb will love this. Great job.', '2017-05-12 21:53:09.000000', NULL, 1),
