(7513403, 1199521, 150202, '<td valign="top">The focus is in the wrong spot for me. The green colors are nice.</td>', 'The focus is in the wrong spot for me. The green colors are nice.', '2017-05-13 01:05:06.000000', NULL, 1),
(7513404, 1199641, 150202, '<td valign="top">A bit too bright for me, but I like the colors.</td>', 'A bit too bright for me, but I like the colors.', '2017-05-13 01:07:58.000000', NULL, 1),
(7513405, 1199699, 150202, '<td valign="top">The softness and colors are nice, although I wish the softness was more uniform as the left eye is too sharp, or alternatively more of the face could be sharp depending on what you were going for.</td>', 'The softness and colors are nice, although I wish the softness was more uniform as the left eye is too sharp, or alternatively more of the face could be sharp depending on what you were going for.', '2017-05-13 01:13:02.000000', NULL, 1),
