(7513407, 1199678, 150202, '<td valign="top">Cute ducks but there is a little too many distractions and dark shadows for my tastes. I like the sharpness.</td>', 'Cute ducks but there is a little too many distractions and dark shadows for my tastes. I like the sharpness.', '2017-05-13 01:19:25.000000', NULL, 1),
(7513408, 1199613, 150202, '<td valign="top">Fits the style and cute scene. The shadows are a bit dark, so the photo comes off a bit harsher then I would like. Nice and sharp.</td>', 'Fits the style and cute scene. The shadows are a bit dark, so the photo comes off a bit harsher then I would like. Nice and sharp.', '2017-05-13 01:23:37.000000', NULL, 1),
(7513409, 1199548, 150202, '<td valign="top">My eye is distracted by the pole in the center, but the scene is really nice, maybe a different angle would have emphasized the girl more. Nice moody lighting.</td>', 'My eye is distracted by the pole in the center, but the scene is really nice, maybe a different angle would have emphasized the girl more. Nice moody lighting.', '2017-05-13 01:26:29.000000', NULL, 1),
