(7513852, 1199616, 28742, '<td valign="top">Way to go, Deb! Melethia would be proud. :)</td>', 'Way to go, Deb! Melethia would be proud. :)', '2017-05-15 01:42:35.000000', NULL, 0),
(7513853, 1199696, 30982, '<td valign="top">Ha!  That''s still one of my favorite entries, and I''m still pi.. irritated that I didn''t get the brown!</td>', 'Ha!  That''s still one of my favorite entries, and I''m still pi.. irritated that I didn''t get the brown!', '2017-05-15 01:43:15.000000', NULL, 0),
(7513854, 1199616, 124815, '<td valign="top">You fooled me. I looked at this several times and could not come up with a comment. Seemed like yours but somehow too sedated, too relaxed! Nothing came to break the peaceful spell of the moment. Well, good for you. Thanks for this image and for all of your work that inspired us and woke us up <strike>for </strike> from a recent dormant spirit.<br/> <br/>sp<br/><br/><i>Message edited by author 2017-05-15 11:45:45.</i></td>', 'You fooled me. I looked at this several times and could not come up with a comment. Seemed like yours but somehow too sedated, too relaxed! Nothing came to break the peaceful spell of the moment. Well, good for you. Thanks for this image and for all of your work that inspired us and woke us up for  from a recent dormant spirit. sp', '2017-05-15 01:45:13.000000', '2017-05-15 12:45:45.000000', 0),
(7513859, 1199693, 30214, '<td valign="top">congrats Lynn! I thought you''d win... I was pretty close. And at least you kicked my butt :)</td>', 'congrats Lynn! I thought you''d win... I was pretty close. And at least you kicked my butt :)', '2017-05-15 02:51:48.000000', NULL, 0),
