(7513866, 1199404, 101668, '<td valign="top">Beautiful image Anita. I did not enter or vote but this is reallly lovely</td>', 'Beautiful image Anita. I did not enter or vote but this is reallly lovely', '2017-05-15 04:26:39.000000', NULL, 0),
(7513872, 1199578, 25024, '<td valign="top">Hello from the critique club<br/> <br/>An appealing image that meets the challenge<br/> <br/>To be honest, I think this is quite an open challenge in that I find it difficult to define a style for Melethia''s photography so with that in mind I could imagine her taking such an image. The image itself is very pleasing, your low-level viewpoint gives an interesting perspective especially given the reflective nature of the floor. I like the mono presentation, though I think there is scope for a little more contrast. This is one of those scenes that would lend itself well to perfect symmetry though I don''t have a problem with this composition. I''ve only just noticed Melethia''s comment so, well done Marcel!</td>', 'Hello from the critique club An appealing image that meets the challenge To be honest, I think this is quite an open challenge in that I find it difficult to define a style for Melethia''s photography so with that in mind I could imagine her taking such an image. The image itself is very pleasing, your low-level viewpoint gives an interesting perspective especially given the reflective nature of the floor. I like the mono presentation, though I think there is scope for a little more contrast. This is one of those scenes that would lend itself well to perfect symmetry though I don''t have a problem with this composition. I''ve only just noticed Melethia''s comment so, well done Marcel!', '2017-05-15 06:37:00.000000', NULL, 0),
(7513877, 1199468, 100831, '<td valign="top">The woman makes an already good scene outstanding, IMO. Congrats! The pacific light is hard to beat.</td>', 'The woman makes an already good scene outstanding, IMO. Congrats! The pacific light is hard to beat.', '2017-05-15 09:39:43.000000', NULL, 0),
(7513878, 1199704, 100831, '<td valign="top">great catch.</td>', 'great catch.', '2017-05-15 09:42:51.000000', NULL, 0),
(7513879, 1199616, 67152, '<td valign="top">Too bad you couldn''t quite nail the style of melethia perfectly.  better luck next time. :)</td>', 'Too bad you couldn''t quite nail the style of melethia perfectly.  better luck next time. :)', '2017-05-15 10:11:51.000000', NULL, 0),
